BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "Test" (
	"Id"	INTEGER,
	"Step"	INTEGER,
	"Method"	TEXT NOT NULL,
	"Uri"	TEXT NOT NULL,
	"JsonGetParameters"	TEXT,
	"JsonPostParameters"	TEXT,
	"JsonConnectedUser"	TEXT,
	"ExpectedResponseCode"	TEXT NOT NULL,
	"Query"	TEXT,
	"QueryExpectedResponse"	TEXT,
	PRIMARY KEY("Id")
);
FROM "Person" p
JOIN "PersonGroup" pg ON pg."IdPerson" = p."Id"
JOIN "Group" g ON g."Id" = pg."IdGroup"
JOIN "GroupAuthorization" ga ON ga."IdGroup" = g."Id"
JOIN "Authorization" a ON a."Id" = ga."IdAuthorization"
GROUP BY p."Email"
